parameters.jsCode:
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  // Flatten field_data array into a plain object
  const fields = {};
  if (Array.isArray(data.field_data)) {
    for (const f of data.field_data) {
      fields[f.name] = Array.isArray(f.values) ? f.values[0] : f.values;
    }
  }

  const name = fields.full_name
    || [fields.first_name, fields.last_name].filter(Boolean).join(' ')
    || data.id
    || 'Unknown';

  const rawPhone = fields.phone_number || fields.phone || '';
  const phone = rawPhone.startsWith('+')
    ? rawPhone
    : rawPhone ? `+91${rawPhone.replace(/^0/, '').replace(/\D/g, '')}` : null;

  results.push({
    json: {
      name,
      email: fields.email || null,
      phone,
      company: fields.company_name || fields.organization || null,
      entityType: fields.job_title || fields.designation || null,
      requirements: fields.message || fields.comments || null,
      sourcePage: 'https://facebook.com/ads',
      _fbLeadId: data.id,
      _fbFormId: data.form_id || null,
      _fbPageId: data.page_id || null,
      _fbAdId: data.ad_id || null,
      _fbCampaignId: data.campaign_id || null,
      _rawFields: fields
    }
  });
}

return results;

